head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > P > accessibility]<br/>컴포넌트에 웹접근성 지원 기능을 일괄적으로 적용할지 설정합니다.",
    "validation" : [
        "renderType=table 인 경우에 동작합니다.",
        "true 설정 시 TreeView 컴포넌트에 웹접근성 지원 기능을 일괄적으로 적용합니다.",
        "true 설정 시 lineShow='false' 가 설정됩니다.",
        "true 설정 시 컴포넌트의 최상위 태그에 tabindex 속성이 설정되지 않습니다.",
        "true 설정 시 컴포넌트의 최상위 태그에 'w2treeview_standard' 클래스가 설정됩니다.",
        "true 설정 시 트리 아이템 요소에 aria-expand, aria-selected, aria-checked 와 같은 HTML 속성들이 추가됩니다.",
        "true 설정 시 트리 아이템 요소가 ul, li 태그로 렌더링 됩니다.",
        "true 설정 시 트리 아이템의 아이콘 영역은 button 태그로, 라벨 영역은 a 태그로 렌더링 됩니다.",
        "true 설정 시 트리 아이템의 아이콘 영역은 'w2treeview_icon_navi_s' 클래스가, 라벨 영역은 'w2anchor2 w2treeview_label' 클래스가 설정됩니다.",
        "미설정 또는 false 설정 시 TreeView 컴포넌트에 웹접근성 지원 기능을 적용하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        accessibility : con_accessibility.getText(),        
    }

    let cList = $c.gcm.createCList(properties);    

    $c.gcm.createBasicTreeView(cList); 
}



scwin.getOptions = function () {
    let rtn = ''

    rtn = target1.options.lineShow;
    wf_body_bottom.getObj("scwin").setReturnValue("lineShow : " + rtn);

    rtn = target1.render.tabIndex;
    wf_body_bottom.getObj("scwin").setReturnValue("tabIndex : " + rtn);

    rtn = target1.render.className;
    wf_body_bottom.getObj("scwin").setReturnValue("className : " + rtn);
}



scwin.getItemInfo = function () {
    let aElement = document.querySelector('a[id*="target1_label_1"]');
    let ulElement = document.querySelector('ul[id*="target1_RootNode_1"]');
    let liElement = document.querySelector('li[id*="target1_node_1"]');
    let iconElement = document.querySelector('button[id*="target1_col_icon_navi_1"]');    

    if (aElement) {
        wf_body_bottom.getObj("scwin").setReturnValue("ariaExpanded : " + aElement.ariaExpanded);
        wf_body_bottom.getObj("scwin").setReturnValue("ariaSelected : " + aElement.ariaSelected);
    }

    if (ulElement && liElement) {
        wf_body_bottom.getObj("scwin").setReturnValue("tag : " + ulElement.tagName + " > " + liElement.tagName);
    }

    if (iconElement && aElement) {
        wf_body_bottom.getObj("scwin").setReturnValue("icon tag : " + iconElement.tagName);
        wf_body_bottom.getObj("scwin").setReturnValue("label tag : " + aElement.tagName);

        wf_body_bottom.getObj("scwin").setReturnValue("icon className : " + iconElement.className);
        wf_body_bottom.getObj("scwin").setReturnValue("label className : " + aElement.className);
    }
}



scwin.btn_accessibility_onclick = function (e) {
    scwin.getOptions();
    scwin.getItemInfo();
}
